/**
 * Iconos de las tecnologías para las tarjetas de proyecto.
 *
 * Cada entrada guarda el nombre visible, el color de marca y el contenido de
 * un <path> de un SVG de 24x24 (pensado para pintarse con `fill`). Los trazos
 * provienen de Simple Icons (CC0); el icono de Java es un dibujo propio y las
 * tecnologías sin marca propia usan el icono genérico de código.
 */

export interface IconoTecnologia {
	/** Nombre legible de la tecnología. */
	nombre: string;
	/** Color de marca en formato hexadecimal. */
	color: string;
	/** Contenido del atributo `d` del <path> del SVG. */
	dibujo: string;
	/** Si es true, el dibujo se pinta con trazo en lugar de relleno. */
	trazo?: boolean;
}

