/** Icono usado cuando la tecnología no está en el catálogo. */
export const iconoPorDefecto: IconoTecnologia = {
	nombre: 'Tecnología',
	color: '#6e6e73',
	dibujo: 'M9.5 5.5 4 12l5.5 6.5M14.5 5.5 20 12l-5.5 6.5',
	trazo: true,
};

/** Variantes escritas por el usuario (clave interna normalizada). */
const alias: Record<string, string> = {
	js: 'javascript',
	ts: 'typescript',
	jsx: 'react',
	tsx: 'react',
	reactjs: 'react',
	angularjs: 'angular',
	vuejs: 'vue',
	next: 'nextjs',
	node: 'nodejs',
	nodejs: 'nodejs',
	'node.js': 'nodejs',
	tailwindcss: 'tailwind',
	postgres: 'postgresql',
	postgre: 'postgresql',
	mongo: 'mongodb',
	k8s: 'kubernetes',
	gcp: 'googlecloud',
	openjdk: 'java',
	jdk: 'java',
	'c++': 'cplusplus',
	'c#': 'csharp',
	csharp: 'csharp',
	net: 'dotnet',
	html5: 'html',
	css3: 'css',
	sql: 'mysql',
	raspberry: 'raspberrypi',
	raspberrypi: 'raspberrypi',
	jpa: 'hibernate',
	jpahibernate: 'hibernate',
	jsonwebtokens: 'jwt',
	amazonwebservices: 'aws',
	apachemaven: 'maven',
	junittest: 'junit5',
	junit4: 'junit5',
	swaggerui: 'swagger',
	openapispecification: 'openapi',
};

/** Normaliza un texto libre a una clave del catálogo. */
function normalizar(texto: string): string {
	return texto
		.trim()
		.toLowerCase()
		.normalize('NFD')
		.replace(/[\u0300-\u036f]/g, '')
		.replace(/[\s._-]+/g, '');
}

/** Devuelve el icono que corresponde a una tecnología escrita por el usuario. */
export function buscarIcono(tecnologia: string): IconoTecnologia {
	const clave = normalizar(tecnologia);
	return iconos[clave] ?? iconos[alias[clave] ?? ''] ?? iconoPorDefecto;
}

/**
 * Indica si un color de marca es tan oscuro que no se vería sobre el fondo
 * oscuro (por ejemplo Vercel, Angular o Next.js). En ese caso el tema oscuro
 * lo aclara para que el icono siga siendo legible.
 */
export function esColorOscuro(color: string): boolean {
	const valor = color.replace('#', '');
	if (valor.length < 6) return false;
	const [r, g, b] = [0, 2, 4].map((i) => parseInt(valor.slice(i, i + 2), 16) / 255);
	const aLineal = (componente: number): number =>
		componente <= 0.03928 ? componente / 12.92 : ((componente + 0.055) / 1.055) ** 2.4;
	const luminancia = 0.2126 * aLineal(r) + 0.7152 * aLineal(g) + 0.0722 * aLineal(b);
	return luminancia < 0.06;
}
